UPDATE "scenes" SET "index" = "numbered"."position" FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "story_id", "chapter_id" ORDER BY "rank", "id") AS "position" FROM "scenes" WHERE "is_deleted" = 0) AS "numbered" WHERE "scenes"."id" = "numbered"."id" AND "scenes"."index" <> "numbered"."position";
