UPDATE "chapters" SET "index" = "numbered"."position" FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "story_id", "type" ORDER BY "rank", "id") AS "position" FROM "chapters" WHERE "is_deleted" = 0) AS "numbered" WHERE "chapters"."id" = "numbered"."id" AND "chapters"."index" <> "numbered"."position";
--> statement-breakpoint
UPDATE "stats" SET "order" = "numbered"."position" FROM (SELECT "id", ROW_NUMBER() OVER (PARTITION BY "story_id" ORDER BY "rank", "id") - 1 AS "position" FROM "stats" WHERE "is_deleted" = 0) AS "numbered" WHERE "stats"."id" = "numbered"."id" AND "stats"."order" <> "numbered"."position";
